Method.Source:
/// <summary>
/// DebuC 05.10.23
/// last modified: PaffH 19.02.25
/// </summary>
/// <param name = "_NDXKumUmsCust">NDXTmpKumUmsCust</param>
/// <param name = "_umsSignature">NDXUmsSignature</param>
/// <param name = "_Firma">NDXCompanyBE</param>
static void Ums(NDXTmpKumUmsCust  _NDXKumUmsCust,
               NDXUmsSignature   _umsSignature,
               NDXCompanyBE        _Firma)
{

    void addUms(NDXMonthBE    _Monat,
             NDXUmsatz     _Umsatz,
             NDXUmsatz     _UmsatzV,
             NDXUmsatz     _UmsatzKum,
             NDXUmsatz     _UmsatzVKum,
             NDXUmsatz     _Bonus,
             NDXUmsatz     _BonusV,
             NDXUmsatz     _BonusKum,
             NDXUmsatz     _BonusVKum)
    {
        NDXKumUmsCustMonat kumUmsCustMonat;
        ;
        kumUmsCustMonat         = NDXKumUmsCustMonat::find(_umsSignature, _Firma, _Monat, true, true);
        kumUmsCustMonat.U       = _Umsatz;
        kumUmsCustMonat.VU      = _UmsatzV;
        kumUmsCustMonat.B       = _Bonus;
        kumUmsCustMonat.VB      = _BonusV;
        kumUmsCustMonat.BKum    = _BonusKum;
        kumUmsCustMonat.VBKum   = _BonusVKum;
        //kumUmsCustMonat.UDiff   = _UmsatzDiff;
        kumUmsCustMonat.UKum    = _UmsatzKum;
        kumUmsCustMonat.VUKum   = _UmsatzVKum;
        kumUmsCustMonat.UDiff   = _UmsatzVKum ? (_UmsatzKum * 100) / _UmsatzVKum : 0;
        if (!_UmsatzVKum && !_UmsatzVKum)
        {
            kumUmsCustMonat.UDiff         = 0;
        }
        else if (!_UmsatzVKum)
        {
            kumUmsCustMonat.UDiff         = 100;
        }
        else
        {
            kumUmsCustMonat.UDiff         -= 100;
        }

        kumUmsCustMonat.write();
    }
    ;
    ttsbegin;
    addUms(NDXMonthBE::January     , _NDXKumUmsCust.U01, _NDXKumUmsCust.VU01, _NDXKumUmsCust.KU01, _NDXKumUmsCust.KVU01, _NDXKumUmsCust.B01, _NDXKumUmsCust.VB01, _NDXKumUmsCust.KB01, _NDXKumUmsCust.KVB01);
    addUms(NDXMonthBE::February    , _NDXKumUmsCust.U02, _NDXKumUmsCust.VU02, _NDXKumUmsCust.KU02, _NDXKumUmsCust.KVU02, _NDXKumUmsCust.B02, _NDXKumUmsCust.VB02, _NDXKumUmsCust.KB02, _NDXKumUmsCust.KVB02);
    addUms(NDXMonthBE::March       , _NDXKumUmsCust.U03, _NDXKumUmsCust.VU03, _NDXKumUmsCust.KU03, _NDXKumUmsCust.KVU03, _NDXKumUmsCust.B03, _NDXKumUmsCust.VB03, _NDXKumUmsCust.KB03, _NDXKumUmsCust.KVB03);
    addUms(NDXMonthBE::April       , _NDXKumUmsCust.U04, _NDXKumUmsCust.VU04, _NDXKumUmsCust.KU04, _NDXKumUmsCust.KVU04, _NDXKumUmsCust.B04, _NDXKumUmsCust.VB04, _NDXKumUmsCust.KB04, _NDXKumUmsCust.KVB04);
    addUms(NDXMonthBE::May         , _NDXKumUmsCust.U05, _NDXKumUmsCust.VU05, _NDXKumUmsCust.KU05, _NDXKumUmsCust.KVU05, _NDXKumUmsCust.B05, _NDXKumUmsCust.VB05, _NDXKumUmsCust.KB05, _NDXKumUmsCust.KVB05);
    addUms(NDXMonthBE::June        , _NDXKumUmsCust.U06, _NDXKumUmsCust.VU06, _NDXKumUmsCust.KU06, _NDXKumUmsCust.KVU06, _NDXKumUmsCust.B06, _NDXKumUmsCust.VB06, _NDXKumUmsCust.KB06, _NDXKumUmsCust.KVB06);
    addUms(NDXMonthBE::July        , _NDXKumUmsCust.U07, _NDXKumUmsCust.VU07, _NDXKumUmsCust.KU07, _NDXKumUmsCust.KVU07, _NDXKumUmsCust.B07, _NDXKumUmsCust.VB07, _NDXKumUmsCust.KB07, _NDXKumUmsCust.KVB07);
    addUms(NDXMonthBE::August      , _NDXKumUmsCust.U08, _NDXKumUmsCust.VU08, _NDXKumUmsCust.KU08, _NDXKumUmsCust.KVU08, _NDXKumUmsCust.B08, _NDXKumUmsCust.VB08, _NDXKumUmsCust.KB08, _NDXKumUmsCust.KVB08);
    addUms(NDXMonthBE::September   , _NDXKumUmsCust.U09, _NDXKumUmsCust.VU09, _NDXKumUmsCust.KU09, _NDXKumUmsCust.KVU09, _NDXKumUmsCust.B09, _NDXKumUmsCust.VB09, _NDXKumUmsCust.KB09, _NDXKumUmsCust.KVB09);
    addUms(NDXMonthBE::October     , _NDXKumUmsCust.U10, _NDXKumUmsCust.VU10, _NDXKumUmsCust.KU10, _NDXKumUmsCust.KVU10, _NDXKumUmsCust.B10, _NDXKumUmsCust.VB10, _NDXKumUmsCust.KB10, _NDXKumUmsCust.KVB10);
    addUms(NDXMonthBE::November    , _NDXKumUmsCust.U11, _NDXKumUmsCust.VU11, _NDXKumUmsCust.KU11, _NDXKumUmsCust.KVU11, _NDXKumUmsCust.B11, _NDXKumUmsCust.VB11, _NDXKumUmsCust.KB11, _NDXKumUmsCust.KVB11);
    addUms(NDXMonthBE::December    , _NDXKumUmsCust.U12, _NDXKumUmsCust.VU12, _NDXKumUmsCust.KU12, _NDXKumUmsCust.KVU12, _NDXKumUmsCust.B12, _NDXKumUmsCust.VB12, _NDXKumUmsCust.KB12, _NDXKumUmsCust.KVB12);
    ttscommit;
}

/// <summary>
/// DebuC 16.10.23
/// last modified: PaffH 19.02.25
/// </summary>
/// <param name = "_NDXUmsSignature">NDXUmsSignature</param>
/// <param name = "_FirmaBE">NDXCompanyBE</param>
/// <param name = "_MonatBE">NDXMonthBE</param>
/// <param name = "_forUpdate">boolean</param>
/// <param name = "_pessimisticlock">boolean</param>
/// <returns>NDXKumUmsCustMonat</returns>
static NDXKumUmsCustMonat find(
    NDXUmsSignature _NDXUmsSignature,
    NDXCompanyBE _FirmaBE,
    NDXMonthBE _MonatBE,
    boolean _forUpdate = false,
    boolean _pessimisticlock = false)
{
    NDXKumUmsCustMonat nDXKumUmsCustMonat;
    nDXKumUmsCustMonat.selectForUpdate(_forUpdate);
    if (_pessimisticlock)
    {
        nDXKumUmsCustMonat.concurrencyModel(ConcurrencyModel::Pessimistic);
    }

    select nDXKumUmsCustMonat
        where nDXKumUmsCustMonat.UmsSignature == _NDXUmsSignature &&
        nDXKumUmsCustMonat.Company == _FirmaBE &&
        nDXKumUmsCustMonat.Month == _MonatBE;

    return nDXKumUmsCustMonat;
}

/// <summary>
/// DebuC 16.10.23
/// </summary>
void initUmsCS()
{
    ;
    this.UCSKum      = 0;
    this.VUCSKum     = 0;
    this.UCSShare    = 0;
    this.VUCSShare   = 0;
    this.BCSKum      = 0;
    this.VBCSKum     = 0;
    this.BCSShare    = 0;
    this.VBCSShare   = 0;

}

/// <summary>
/// DebuC 16.10.23
/// </summary>
void initUms()
{
    ;
    this.U         = 0;
    this.VU        = 0;
    this.UKum      = 0;
    this.VUKum     = 0;
    this.UDiff     = 0;
    this.B         = 0;
    this.VB        = 0;
    this.BKum      = 0;
    this.VBKum     = 0;
}

/// <summary>
/// DebuC 16.10.23
/// last modified: PaffH 19.02.25
/// </summary>
/// <param name = "_umsSignature">NDXUmsSignature</param>
static void UmsCSAlleFirmen(NDXUmsSignature _umsSignature)
{
    void setUms(NDXMonthBE _Monat)
    {
        NDXKumUmsCustMonat  kumUmsCustMonat, kumUmsCustMonatGrp;
        Query               q;
        QueryRun            qr;
        QueryBuildDataSource    qbd;
        QueryBuildFieldList     fieldList;
        ttsbegin;
        kumUmsCustMonat = NDXKumUmsCustMonat::find(_umsSignature, NDXCompanyBE::AllCompanies, _Monat, true, true);

        if (!kumUmsCustMonat)
        {
            ttsabort;
            return;
        }

        q   = new Query();
        qbd = q.addDataSource(tablenum(NDXKumUmsCustMonat));
        qbd.addRange(fieldnum(NDXKumUmsCustMonat, UmsSignature)).value(_umsSignature);
        qbd.addRange(fieldnum(NDXKumUmsCustMonat, Company)).value(SysQuery::valueNot(NDXCompanyBE::AllCompanies));
        qbd.addRange(fieldnum(NDXKumUmsCustMonat, Month)).value(QueryValue(_Monat));

        qbd.orderMode(OrderMode::GroupBy);
        fieldList           = qbd.fields();

        fieldList.addField(fieldnum(NDXKumUmsCustMonat, UCSShare ), SelectionField::Sum);
        fieldList.addField(fieldnum(NDXKumUmsCustMonat, VUCSShare), SelectionField::Sum);
        fieldList.addField(fieldnum(NDXKumUmsCustMonat, U        ), SelectionField::Sum);
        fieldList.addField(fieldnum(NDXKumUmsCustMonat, VU       ), SelectionField::Sum);
        fieldList.addField(fieldnum(NDXKumUmsCustMonat, UKum     ), SelectionField::Sum);
        fieldList.addField(fieldnum(NDXKumUmsCustMonat, VUKum    ), SelectionField::Sum);
        fieldList.addField(fieldnum(NDXKumUmsCustMonat, UCSShareExcl ), SelectionField::Sum);
        fieldList.addField(fieldnum(NDXKumUmsCustMonat, VUCSShareExcl), SelectionField::Sum);

        qr = new QueryRun(q);
        qr.next();
        kumUmsCustMonatGrp = qr.get(tablenum(NDXKumUmsCustMonat));

        kumUmsCustMonat.UCSShare            = kumUmsCustMonatGrp.UCSShare;
        kumUmsCustMonat.VUCSShare           = kumUmsCustMonatGrp.VUCSShare;
        kumUmsCustMonat.U                   = kumUmsCustMonatGrp.U;
        kumUmsCustMonat.VU                  = kumUmsCustMonatGrp.VU;
        kumUmsCustMonat.UKum                = kumUmsCustMonatGrp.UKum;
        kumUmsCustMonat.VUKum               = kumUmsCustMonatGrp.VUKum;
        kumUmsCustMonat.UCSShareExcl        = kumUmsCustMonatGrp.UCSShareExcl;
        kumUmsCustMonat.VUCSShareExcl       = kumUmsCustMonatGrp.VUCSShareExcl;
        kumUmsCustMonat.UCSSharePercent     = (kumUmsCustMonat.UCSShareExcl + kumUmsCustMonat.UCSShare  ) ? (kumUmsCustMonat.UCSShare * 100)  / (kumUmsCustMonat.UCSShareExcl + kumUmsCustMonat.UCSShare)   : 0;
        kumUmsCustMonat.VUCSSharePercent    = (kumUmsCustMonat.VUCSShareExcl + kumUmsCustMonat.VUCSShare) ? (kumUmsCustMonat.VUCSShare * 100) / (kumUmsCustMonat.VUCSShareExcl + kumUmsCustMonat.VUCSShare) : 0;
        kumUmsCustMonat.update();
        ttscommit;
    }

    setUms(NDXMonthBE::January    );
    setUms(NDXMonthBE::February   );
    setUms(NDXMonthBE::March     );
    setUms(NDXMonthBE::April     );
    setUms(NDXMonthBE::May       );
    setUms(NDXMonthBE::June      );
    setUms(NDXMonthBE::July      );
    setUms(NDXMonthBE::August    );
    setUms(NDXMonthBE::September );
    setUms(NDXMonthBE::October   );
    setUms(NDXMonthBE::November  );
    setUms(NDXMonthBE::December  );
}

/// <summary>
/// DebuC 05.10.23
/// last modified: PaffH 12.02.25
/// </summary>
/// <param name = "_AccountNum">AccountNum</param>
/// <param name = "_umsSignature">NDXUmsSignature</param>
/// <param name = "monthYearSignature">NDXMonthYearSignature</param>
/// <param name = "_Firma">NDXCompanyBE</param>
/// <param name = "_yearLfd">NDXYear</param>
/// <param name = "_yearVJ">NDXYear</param>
/// <param name = "lExcl">boolean</param>
/// <param name = "umsSignatureForm">NDXUmsSignature</param>
static void UmsCS(
    AccountNum _AccountNum,
    NDXUmsSignature _umsSignature,
    NDXMonthYearSignature monthYearSignature,
    NDXCompanyBE _Firma,
    NDXYear _yearLfd,
    NDXYear _yearVJ,
    boolean lExcl = false,
    NDXUmsSignature umsSignatureForm = _umsSignature)
{
    #AviFiles

    NDXTmpCSAllianceMap                nDX_TmpCSAllianceMap;
    NDXKumUmsCust                      kumUmsCust, kumUmsCustVJ;
    NDXKumBonCust                      kumBonCust, kumBonCustVJ;
    Array                               uArray, vuArray;
    Array                               bArray, vbArray;        
    Array                               cArray, vcArray;        
    Integer                             i;
    CompanyId                           company;
    NDXUmsatz                          kumUms, kumUmsVJ, kumUmsAll, kumUmsVJAll;
    NDXUmsatz                          kumBon, kumBonVJ, kumBonAll, kumBonVJAll;
    NDXCostAmount                      kumCost, kumCostVJ, kumCostAll, kumCostVJAll;
    Map                                 mapFieldPrefix;
    SysDictTable                        dictTableUms, dictTableBon;
    FieldId                             uFieldId, bFieldId, cFieldId;
    str                                 uField;
    str                                 bField;
    str                                 cField;
    str                                 fieldPrefix;
    DictEnum                            enumMonat;

    Query                               q;
    QueryRun                            qr;
    QueryBuildDataSource                qbds;        
    int                                 total, total1;
    SysOperationProgress                progress;


    /// <summary>
    /// DebuC 05.10.23
    /// Feldprefix ermitteln
    /// </summary>
    /// <param name = "_Monat">NDXMonthBE</param>
    str getFieldPrefix(NDXMonthBE _Monat)
    {
        if (!mapFieldPrefix.exists(_Monat))
        {
            throw error(strfmt("@NDX:NDXKumUmsCustMonatNotFound", _Monat));
        }

        return mapFieldPrefix.lookup(_Monat);
    }

    /// <summary>
    /// DebuC 05.10.23
    /// last modified: PaffH 17.02.25
    /// Umsatzwerte in NDX_TmpCSAlliance speichern
    /// </summary>
    /// <param name = "_Monat">NDXMonthBE</param>
    /// <param name = "_Umsatz">NDXUmsatz</param>
    /// <param name = "_UmsatzVJ">NDXUmsatz</param>
    /// <param name = "_Bonus">NDXUmsatz</param>
    /// <param name = "_BonusVJ">NDXUmsatz</param>
    /// <param name = "_Cost">NDXCostAmount</param>
    /// <param name = "_CostVJ">NDXCostAmount</param>
    void addUms(NDXMonthBE    _Monat,
             NDXUmsatz     _Umsatz,
             NDXUmsatz     _UmsatzVJ,
             NDXUmsatz     _Bonus,
             NDXUmsatz     _BonusVJ,
             NDXCostAmount _Cost,
             NDXCostAmount _CostVJ)
    {
        #define.Umsatz('Umsatz')
        #define.Bonus('Bonus')
        #define.U('U')
        #define.VU('VU')
        #define.B('B')
        #define.VB('VB')
        #define.C('C')
        #define.VC('VC')
        DictTable       dictTable;           
        fieldId         fieldId;
        real            umsatz, vUmsatz;
        int             j;
        ;

        fieldPrefix     = getFieldPrefix(_Monat);

        dictTable       = new SysDictTable(tablenum(NDXTmpCSAllianceMap));
        for (j = 1; j <= 2; j++)
        {
            // Umsatz
            uField          = strfmt('%1%2', ( j == 1 ? #U : #VU), fieldPrefix);
            fieldId         = dictTable.fieldName2Id(uField);
            nDX_TmpCSAllianceMap.(fieldId) += (j == 1 ? _Umsatz : _UmsatzVJ);

            // Bonus
            uField          = strfmt('%1%2', ( j == 1 ? #B : #VB), fieldPrefix);
            fieldId         = dictTable.fieldName2Id(uField);
            nDX_TmpCSAllianceMap.(fieldId) += (j == 1 ? _Bonus  : _BonusVJ);

            // Einstand
            uField          = strfmt('%1%2', ( j == 1 ? #C : #VC), fieldPrefix);
            fieldId         = dictTable.fieldName2Id(uField);
            nDX_TmpCSAllianceMap.(fieldId) += (j == 1 ? _Cost  : _CostVJ);
        }

        // Umsatz akt. Jahr
        umsatz = uArray.value(_Monat);
        uArray.value(_Monat, umsatz + _Umsatz);

        // Vorjahresumsatz
        vUmsatz = vuArray.value(_Monat);
        vuArray.value(_Monat, vumsatz + _UmsatzVJ);

        // Bonus akt. Jahr
        umsatz = bArray.value(_Monat);
        bArray.value(_Monat, umsatz + _Bonus);

        // Vorjahresbonus
        vUmsatz = vbArray.value(_Monat);
        vbArray.value(_Monat, vumsatz + _BonusVJ);

        // Einstand akt. Jahr
        umsatz = cArray.value(_Monat);
        cArray.value(_Monat, umsatz + _Cost);

        // Vorjahreseinstand
        vUmsatz = vcArray.value(_Monat);
        vcArray.value(_Monat, vumsatz + _CostVJ);
    }

    /// <summary>
    /// DebuC 05.10.23
    /// last modified: PaffH 19.02.25
    // kumulierte Zentrallagerumsätze speichern
    /// </summary>
    /// <param name = "_Monat">NDXMonthBE</param>
    void setUms(NDXMonthBE _Monat)
    {
        System.Exception ex;
        #define.FirmaAll(2)
        NDXKumUmsCustMonat kumUmsCustMonat;
        NDXUmsatz u, uV;
        int j;

        try
        {
            ttsbegin;
            if (_Monat == NDXMonthBE::January)
            {
                kumUms          = 0;
                kumUmsVJ        = 0;
                kumUmsAll       = 0;
                kumUmsVJAll     = 0;
                kumBon          = 0;
                kumBonVJ        = 0;
                kumBonAll       = 0;
                kumBonVJAll     = 0;
                kumCost         = 0;
                kumCostVJ       = 0;
                kumCostAll      = 0;
                kumCostVJAll    = 0;
            }
            for (j = 1; j <= 2; j++)
            {
                if (j == #FirmaAll)
                {
                    kumUmsCustMonat             = NDXKumUmsCustMonat::find(umsSignatureForm, NDXCompanyBE::AllCompanies, _Monat, true, true);
                    kumUmsAll                   += uArray.value(_Monat);
                    kumUmsVJAll                 += vuArray.value(_Monat);
                    kumUmsCustMonat.UCSKum      += kumUmsAll;
                    kumUmsCustMonat.VUCSKum     += kumUmsVJAll;
                    kumUmsCustMonat.UCSShare    += uArray.value(_Monat);
                    kumUmsCustMonat.VUCSShare   += vuArray.value(_Monat);

                    kumBonAll                   += bArray.value(_Monat);
                    kumBonVJAll                 += vbArray.value(_Monat);
                    kumUmsCustMonat.BCSKum      += kumBonAll;
                    kumUmsCustMonat.VBCSKum     += kumBonVJAll;
                    kumUmsCustMonat.BCSShare    += bArray.value(_Monat);
                    kumUmsCustMonat.VBCSShare   += vbArray.value(_Monat);

                    kumCostAll                  += cArray.value(_Monat);
                    kumCostVJAll                += vcArray.value(_Monat);
                    kumUmsCustMonat.CCSKum      += kumCostAll;
                    kumUmsCustMonat.VCCSKum     += kumCostVJAll;
                    kumUmsCustMonat.CCSShare    += cArray.value(_Monat);
                    kumUmsCustMonat.VCCSShare   += vcArray.value(_Monat);
                }
                else
                {
                    kumUmsCustMonat             = NDXKumUmsCustMonat::find(umsSignatureForm, _Firma, _Monat, true, true);
                    kumUms                      += uArray.value(_Monat);
                    kumUmsVJ                    += vuArray.value(_Monat);
                    kumUmsCustMonat.UCSKum      = kumUms;
                    kumUmsCustMonat.VUCSKum     = kumUmsVJ;
                    kumUmsCustMonat.UCSShare    = uArray.value(_Monat);
                    kumUmsCustMonat.VUCSShare   = vuArray.value(_Monat);

                    kumBon                      += bArray.value(_Monat);
                    kumBonVJ                    += vbArray.value(_Monat);
                    kumUmsCustMonat.BCSKum      = kumBon;
                    kumUmsCustMonat.VBCSKum     = kumBonVJ;
                    kumUmsCustMonat.BCSShare    = bArray.value(_Monat);
                    kumUmsCustMonat.VBCSShare   = vbArray.value(_Monat);

                    kumCost                     += cArray.value(_Monat);
                    kumCostVJ                   += vcArray.value(_Monat);
                    kumUmsCustMonat.CCSKum      = kumCost;
                    kumUmsCustMonat.VCCSKum     = kumCostVJ;
                    kumUmsCustMonat.CCSShare    = cArray.value(_Monat);
                    kumUmsCustMonat.VCCSShare   = vcArray.value(_Monat);
                }
                // aktuelles Jahr
                kumUmsCustMonat.UCSShareExcl        = kumUmsCustMonat.U;
                u                                  = kumUmsCustMonat.U + kumUmsCustMonat.UCSShare;
                kumUmsCustMonat.UCSSharePercent     = u ? (kumUmsCustMonat.UCSShare * 100) / u : 0;

                // Vorjahr
                kumUmsCustMonat.VUCSShareExcl       = kumUmsCustMonat.VU;
                u                                  = kumUmsCustMonat.VU + kumUmsCustMonat.VUCSShare;
                kumUmsCustMonat.VUCSSharePercent    = u ? (kumUmsCustMonat.VUCSShare * 100) / u : 0;

                //Differenz
                uV                                 = kumUmsCustMonat.VUKum + kumUmsCustMonat.VUCSKum;
                u                                  = kumUmsCustMonat.UKum  + kumUmsCustMonat.UCSKum;
                kumUmsCustMonat.UCSDiff             = uV ? (u * 100) / uV : 0;
                if (!u && !uV)
                {
                    kumUmsCustMonat.UCSDiff         = 0;
                }
                else if (!uV)
                {
                    kumUmsCustMonat.UCSDiff         = 100;
                }
                else
                {
                    kumUmsCustMonat.UCSDiff         -= 100;
                }
                if (abs(kumUmsCustMonat.UCSDiff) > 1000000)
                {
                    kumUmsCustMonat.UCSDiff = 0;
                }
                kumUmsCustMonat.write();
            }
            ttscommit;
        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= NDXConstants::RetryNum)
            {
                throw Exception::Deadlock;
            }
            else
            {
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= NDXConstants::RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch (ex)
        {
            throw Error(ex.Message);
        }
    }

    /// <summary>
    /// DebuC 05.10.23
    /// </summary>
    NDXUmsatz getUmsAnteil(NDXUmsatz _Umsatz, NDXCSDPct _cSDPct)
    {
        return ((_Umsatz * _cSDPct) / 100);
    }

    /// <summary>
    /// DebuC 05.10.23
    /// Initialisierung der Kumulierungs-Arrays
    /// </summary>
    void initUArray(NDXMonthBE monat)
    {
        uArray.value(monat, 0.0);
        vuArray.value(monat, 0.0);
        bArray.value(monat, 0.0);
        vbArray.value(monat, 0.0);
        cArray.value(monat, 0.0);
        vcArray.value(monat, 0.0);
    }

    ;
    #define.Umsatz('Umsatz')
    #define.Bonus('Bonus')
    #define.CostAmount('CostAmount')

    enumMonat       = new DictEnum(enumnum(NDXMonthBE));
    mapFieldPrefix  = NDXUmsatzClass::getFieldPrefixFromNDX_MonatBE();
    uArray      = new Array(Types::Real);
    vuArray     = new Array(Types::Real);
    bArray      = new Array(Types::Real);
    vbArray     = new Array(Types::Real);
    cArray      = new Array(Types::Real);
    vcArray     = new Array(Types::Real);
    for (i = 1; i < enumMonat.values(); i++)
    {
        initUArray(enumMonat.index2Value(i));
    }

    company = NDXHelperCommon::NDXCompanys2CompanyId(_Firma);

    // Zentrallageranteile sammeln
    q   = new Query();
    qbds = q.addDataSource(tablenum(NDXTmpCSAlliance));
    qbds.addRange(fieldnum(NDXTmpCSAlliance, UmsSignature)).value(_umsSignature);
    qbds.addRange(fieldnum(NDXTmpCSAlliance, MonthYearSignature)).value(monthYearSignature);
    qbds.addRange(fieldnum(NDXTmpCSAlliance, Exclude)).value(enum2str(lExcl ? NoYes::Yes : NoYes::No));
    qbds.addRange(fieldnum(NDXTmpCSAlliance, Company)).value(company);
    qbds.addRange(fieldnum(NDXTmpCSAlliance, Alliance)).value(_AccountNum);
    //qbds.addRange(fieldnum(NDX_TmpCSAlliance, CustAccount)).value(_AccountNum);
    qbds.update(true);
    qr = new QueryRun(q);

    progress    = SysOperationProgress::newMultiBar(2, #aviUpdate, strfmt('[%1] ZL-Anteile', _Firma));     // Artikelgruppenumsatz ermitteln
    total      = SysQuery::countTotal(qr);
    progress.setTotal(total, 1);

    //NDX_KumUmsCustArtGrp::InitUmsCS(nDX_TmpCSAllianceMap, _yearLfd, false);

    dictTableUms    = new SysDictTable(tablenum(NDXKumUmsCust));
    dictTableBon    = new SysDictTable(tablenum(NDXKumBonCust));

    while (qr.next())
    {
        nDX_TmpCSAllianceMap    = qr.get(tablenum(NDXTmpCSAlliance));


        ++total1;
        progress.setCount(total1, 1);
        progress.setText(strfmt('(%1/%2) - %3', total1, total,  nDX_TmpCSAllianceMap.CentralStoreId), 1);


        //Debug::printDebug(strfmt("%1: %2", nDX_CentralStoreDistributionTable.CentralStoreId, nDX_CentralStoreDistributionLine.CSDPct));
        kumUmsCust      = NDXKumUmsCust::find(_firma, nDX_TmpCSAllianceMap.CentralStoreId, _yearLfd);
        kumUmsCustVJ    = NDXKumUmsCust::find(_firma, nDX_TmpCSAllianceMap.CentralStoreId, _yearVJ);
        kumBonCust      = NDXKumBonCust::find(_firma, nDX_TmpCSAllianceMap.CentralStoreId, _yearLfd);
        kumBonCustVJ    = NDXKumBonCust::find(_firma, nDX_TmpCSAllianceMap.CentralStoreId, _yearVJ);

        ttsbegin;
        nDX_TmpCSAllianceMap.nDXTmpCSAllianceMap::initUJahr();
        nDX_TmpCSAllianceMap.nDXTmpCSAllianceMap::initVUJahr();
        nDX_TmpCSAllianceMap.nDXTmpCSAllianceMap::initBJahr();
        nDX_TmpCSAllianceMap.nDXTmpCSAllianceMap::initVBJahr();
        nDX_TmpCSAllianceMap.nDXTmpCSAllianceMap::initCJahr();
        nDX_TmpCSAllianceMap.nDXTmpCSAllianceMap::initVCJahr();
        if (kumUmsCust || kumUmsCustVJ || kumBonCust || kumBonCustVJ )
        {
            for (i = 1; i < enumMonat.values(); i++)
            {
                fieldPrefix     = getFieldPrefix(i);

                // Umsatz
                uField          = strfmt('%1%2', #Umsatz, fieldPrefix);
                uFieldId        = dictTableUms.fieldName2Id(uField);
                // Bonus
                bField          = strfmt('%1%2', #Bonus, fieldPrefix);
                bFieldId        = dictTableBon.fieldName2Id(bField);
                // Einstandspreis
                cField          = strfmt('%1%2', #CostAmount, fieldPrefix);
                cFieldId        = dictTableUms.fieldName2Id(cField);

                addUms(enumMonat.index2Value(i),
                    getUmsAnteil(kumUmsCust.(uFieldId)  , nDX_TmpCSAllianceMap.CSDPctLfdJ),
                    getUmsAnteil(kumUmsCustVJ.(uFieldId), nDX_TmpCSAllianceMap.CSDPctVJ)  ,
                    getUmsAnteil(kumBonCust.(bFieldId)  , nDX_TmpCSAllianceMap.CSDPctLfdJ),
                    getUmsAnteil(kumBonCustVJ.(bFieldId), nDX_TmpCSAllianceMap.CSDPctVJ)  ,
                    getUmsAnteil(kumUmsCust.(cFieldId)  , nDX_TmpCSAllianceMap.CSDPctLfdJ),
                    getUmsAnteil(kumUmsCustVJ.(cFieldId), nDX_TmpCSAllianceMap.CSDPctVJ)  );

            }
            // Artikelgruppenanteile ermitteln
            //TODO: Aussparen?: NDX_KumUmsCustArtGrp::getUmsCS(nDX_TmpCSAllianceMap, _yearLfd, false);
            //NDX_KumUmsCustArtGrp::getUmsCS(nDX_TmpCSAllianceMap, _yearLfd, false);
        }
        nDX_TmpCSAllianceMap.update();
        ttscommit;
    }

    // kumulierte Zentrallagerumsätze für Formdarstellung speichern
    if (!lExcl)
    {
        setUms(NDXMonthBE::January   );
        setUms(NDXMonthBE::February  );
        setUms(NDXMonthBE::March     );
        setUms(NDXMonthBE::April     );
        setUms(NDXMonthBE::May       );
        setUms(NDXMonthBE::June      );
        setUms(NDXMonthBE::July      );
        setUms(NDXMonthBE::August    );
        setUms(NDXMonthBE::September );
        setUms(NDXMonthBE::October   );
        setUms(NDXMonthBE::November  );
        setUms(NDXMonthBE::December  );
    }
}
